begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(17);
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data) values
('a8700000-0000-4000-8000-000000000001','browser-a@example.test','{"provider":"email"}','{"username":"browser_a"}'),
('a8700000-0000-4000-8000-000000000002','browser-b@example.test','{"provider":"email"}','{"username":"browser_b"}');
select ok((select relrowsecurity from pg_class where oid='public.session_browser_tabs'::regclass),'Browser state has RLS');
select ok(not has_table_privilege('authenticated','public.session_browser_tabs','INSERT,UPDATE,DELETE'),'Browser state cannot be forged directly');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a8700000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('test.browser_session',(public.start_study_session(null,'rain-desk',null,'{"mode":"solo","characterSlugs":[]}')).id::text,true);
select public.sync_session_browser(current_setting('test.browser_session')::uuid,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000011');
select public.close_session_browser_tab(current_setting('test.browser_session')::uuid,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000011');
reset role;
select ok((select closed_at is not null from session_browser_tabs where session_id=current_setting('test.browser_session')::uuid),'Close uses a server timestamp');
set local role authenticated;
select public.sync_session_browser(current_setting('test.browser_session')::uuid,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000012',true);
select public.close_session_browser_tab(current_setting('test.browser_session')::uuid,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000011');
reset role;
select ok((select closed_at is null from session_browser_tabs where session_id=current_setting('test.browser_session')::uuid),'Reload cancels close; delayed old-document close is ignored');
select is((select ended_at from sessions where id=current_setting('test.browser_session')::uuid),null::timestamptz,'Reload keeps original session running');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a8700000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select public.close_session_browser_tab(current_setting('test.browser_session')::uuid,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000012');
reset role;
select ok((select closed_at is null from session_browser_tabs where session_id=current_setting('test.browser_session')::uuid),'Another account cannot close the browser session');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a8700000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.close_session_browser_tab(current_setting('test.browser_session')::uuid,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000012');
reset role;
select set_config('test.browser_closed_at',(select closed_at::text from session_browser_tabs where session_id=current_setting('test.browser_session')::uuid),true);
set local role authenticated;
select public.sync_session_browser(current_setting('test.browser_session')::uuid,'00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000022');
reset role;
select is((select ended_reason from sessions where id=current_setting('test.browser_session')::uuid),'stopped_early','New tab settles the closed session immediately');
select is((select ended_at from sessions where id=current_setting('test.browser_session')::uuid),current_setting('test.browser_closed_at')::timestamptz,'Closed time is excluded from banking');
select is((select count(*) from session_browser_tabs where session_id=current_setting('test.browser_session')::uuid),0::bigint,'Finished browser tracking is cleaned');
select is((select total_seconds from day_stats where user_id='a8700000-0000-4000-8000-000000000001'),(select actual_seconds::bigint from sessions where id=current_setting('test.browser_session')::uuid),'Database trigger banks time exactly once');
select is((select best_streak from streaks where user_id='a8700000-0000-4000-8000-000000000001'),1,'Closing a tab preserves earned activity');
set local role authenticated;
select public.sync_session_browser(current_setting('test.browser_session')::uuid,'00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000022');
select set_config('test.browser_session',(public.start_study_session(null,'rain-desk',null,'{"mode":"solo","characterSlugs":[]}')).id::text,true);
select public.sync_session_browser(current_setting('test.browser_session')::uuid,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000011');
select public.sync_session_browser(current_setting('test.browser_session')::uuid,'00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000022');
select public.close_session_browser_tab(current_setting('test.browser_session')::uuid,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000011');
select public.sync_session_browser(current_setting('test.browser_session')::uuid,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000011');
reset role;
select ok((select closed_at is not null from session_browser_tabs where session_id=current_setting('test.browser_session')::uuid and tab_id='00000000-0000-4000-8000-000000000001'),'In-flight read cannot reopen its closed document');
select is((select ended_at from sessions where id=current_setting('test.browser_session')::uuid),null::timestamptz,'Another open tab keeps the session running');
set local role authenticated;
select public.close_session_browser_tab(current_setting('test.browser_session')::uuid,'00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000022');
reset role;
update session_browser_tabs set closed_at=clock_timestamp()-interval '31 seconds' where session_id=current_setting('test.browser_session')::uuid;
select public.maintain_study_leases();
select ok((select ended_at is not null from sessions where id=current_setting('test.browser_session')::uuid),'Maintenance settles the final closed tab');
select public.maintain_study_leases();
select is((select sum(total_seconds)::bigint from day_stats where user_id='a8700000-0000-4000-8000-000000000001'),(select sum(actual_seconds) from sessions where user_id='a8700000-0000-4000-8000-000000000001'),'Repeated maintenance does not duplicate credit');
set local role anon;
select throws_ok($$select public.sync_session_browser()$$,'42501',null,'Anonymous callers cannot access browser state');
select throws_ok($$select public.close_session_browser_tab(gen_random_uuid(),gen_random_uuid(),gen_random_uuid())$$,'42501',null,'Anonymous callers cannot send close signals');
reset role;
select * from finish();
rollback;
